# -*- coding: utf-8 -*-
"""玩具寄售清单 - 一键安装引导（运行一次即可，可删除）"""
import base64, os

TARGET = os.path.join(os.path.expanduser("~"), "玩具寄售", "toy_consignment.py")

# ======== 内嵌完整应用代码（base64） ========
_B64 = ""

def main():
    os.makedirs(os.path.dirname(TARGET), exist_ok=True)
    try:
        code = base64.b64decode(_B64).decode("utf-8")
        with open(TARGET, "w", encoding="utf-8") as f:
            f.write(code)
        print("=" * 50)
        print("✅ 安装成功！")
        print("   完整应用已保存到：")
        print("   " + TARGET)
        print()
        print("👉 请在 Pythonista 文件列表中找到")
        print("   玩具寄售 / toy_consignment.py")
        print("   点击打开，再点 ▶ 运行即可。")
        print()
        print("（本引导脚本可以删除）")
        print("=" * 50)
    except Exception as e:
        print("❌ 安装失败: " + str(e))

if __name__ == "__main__":
    main()
